.eon8-live-page .sme-section-eon {
  width: 100%;
  padding: 10px 20px;
  display: flex;
  justify-content: center;
  font-family: Arial, sans-serif;
}
.eon8-live-page .sme-container {
  max-width: 1100px;
  width: 100%;
}
.eon8-live-page .sme-header {
  text-align: center;
  margin-bottom: 50px;
}
.eon8-live-page .sme-title {
  font-size: 30px;
  font-weight: 700;
  color: #111827;
}
.eon8-live-page .sme-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 25px;
}
.eon8-live-page .sme-card {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  padding: 25px;
  transition: all 0.35s ease;
  position: relative;
  overflow: hidden;
}
.eon8-live-page .sme-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 20px 40px rgba(0,0,0,0.1);
}
.eon8-live-page .sme-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 14px;
  padding: 1px;
  background: linear-gradient(120deg, transparent, #0b3c8a, transparent);
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  opacity: 0;
  transition: 0.4s;
}
.eon8-live-page .sme-card:hover::before {
  opacity: 1;
}
.eon8-live-page .sme-number {
  width: 45px;
  height: 45px;
  background: #0b3c8a;
  color: #fff;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  margin-bottom: 15px;
  transition: 0.3s ease;
}
.eon8-live-page .sme-card:hover .sme-number {
  transform: scale(1.1) rotate(5deg);
}
.eon8-live-page .sme-card h3 {
  font-size: 18px;
  margin-bottom: 10px;
  color: #111827;
}
.eon8-live-page .sme-card ul {
  padding-left: 18px;
  margin: 10px 0;
  color: #4b5563;
  font-size: 14px;
  line-height: 1.6;
}
.eon8-live-page .sme-card p {
  font-size: 14px;
  color: #6b7280;
}
.eon8-live-page .animate-eon {
  opacity: 0;
  transform: translateY(40px);
  transition: all 0.7s ease;
}
.eon8-live-page .animate-eon.show {
  opacity: 1;
  transform: translateY(0);
}
